sys_script_include.script:
var WardService = Class.create();

WardService.prototype = {

    initialize: function() {
        this.validationUtils = new ValidationUtils();
    },

    wardExists: function(wardSysId) {

        if (this.validationUtils.isEmpty(wardSysId)) {
            return false;
        }

        var ward = new GlideRecord(
            'x_2130921_caresy_0_ward'
        );

        if (!ward.isValid()) {
            gs.error(
                'WardService: Ward table is invalid.'
            );
            return false;
        }

        return ward.get(wardSysId);
    },

    getWard: function(wardSysId) {

        if (this.validationUtils.isEmpty(wardSysId)) {
            return null;
        }

        var ward = new GlideRecord(
            'x_2130921_caresy_0_ward'
        );

        if (!ward.isValid()) {
            gs.error(
                'WardService: Ward table is invalid.'
            );
            return null;
        }

        if (ward.get(wardSysId)) {
            return ward;
        }

        return null;
    },

    isWardActive: function(wardSysId) {

        var ward = this.getWard(wardSysId);

        if (!ward) {
            return false;
        }

        return ward.getValue('active') == '1';
    },

    type: 'WardService'
};
